def boundary(s):
    """Boundary of an oriented simplex s, as {face: coefficient}."""
    chain = {}
    for x in s:
        face = tuple(y for y in s if y != x)
        chain[face] = chain.get(face, 0) + (-1) ** sum(1 for y in s if y < x)
    return {f: c for f, c in chain.items() if c != 0}

def boundary_squared(s):
    """Compose the boundary with itself; provably returns the empty (zero) chain."""
    total = {}
    for face1, c1 in boundary(s).items():
        for face2, c2 in boundary(face1).items():
            total[face2] = total.get(face2, 0) + c1 * c2
    return {f: c for f, c in total.items() if c != 0}  # always {}

from itertools import combinations

def euler_characteristic(vertices, edges):
    """Reduced Euler characteristic of the clique complex: sum_k (-1)^k * (#(k+1)-cliques)."""
    edges = {frozenset(e) for e in edges}
    def is_clique(c):
        return all(frozenset((a, b)) in edges for a, b in combinations(c, 2))
    chi = 0
    for k in range(1, len(vertices) + 1):
        count = sum(1 for c in combinations(vertices, k) if is_clique(c))
        chi += (-1) ** (k - 1) * count
    return chi
